import type { JsonSchema } from "../casing/schemaKeyCasing";
import type { Overlay } from "../overlay/overlay";
import { emitFixtureType, objectMembers } from "./emitType";

const GENERATED_HEADER = `// Generated by @autumn/atmn-generator from packages/openapi/openapi-internal.yml.
// Do not edit — run \`bun generate\` in packages/atmn-generator instead.
`;

/** A singleton is stated as a plain object, so it gets a type and no builder. */
export const emitSingletonModule = ({
	name,
	typeName,
	schema,
	overlay,
}: {
	name: string;
	typeName: string;
	schema: JsonSchema;
	overlay: Overlay;
}): string =>
	[
		GENERATED_HEADER,
		emitFixtureType({ name: typeName, schema, collection: name, overlay }),
	].join("\n");

export type SingletonField = {
	/** The fixture key, renamed by the overlay where it says so. */
	key: string;
	wireKey: string;
	/** The server's default: a value back at it is a pair pull removes. */
	default: unknown;
};

/** What each fixture key is on the wire and what the server defaults it to. */
export const singletonFields = ({
	name,
	schema,
	overlay,
}: {
	name: string;
	schema: JsonSchema;
	overlay: Overlay;
}): SingletonField[] =>
	objectMembers({
		schema,
		path: "",
		context: { overlay, collection: name },
	}).map((member) => ({
		key: member.name,
		wireKey: member.fieldPath,
		default: member.schema.default,
	}));
